mapper.select:
select a.source_id, a.article_key, a.concept_id, a.title, a.content, a.metadata_json::text as metadata_json, a.review_status, a.source_paths, 0
+ case when lower(a.refkey_text) like #{pattern} then 5.0 else 0 end + case when lower(a.concept_id) like #{pattern} then 4.0 else 0 end + case when lower(a.title) like #{pattern} then 2.0 else 0 end + case when lower(a.metadata_json::text) like #{pattern} then 1.0 else 0 end
as score from articles a where false
or lower(a.refkey_text) like #{pattern} or lower(a.concept_id) like #{pattern} or lower(a.title) like #{pattern} or lower(a.metadata_json::text) like #{pattern}
order by score desc, a.compiled_at desc, a.article_key asc limit #{limit}
